"""
Step 15 -- Diagram Regeneration

The original project's diagrams/ folder (figure1_data_cleaning_pipeline.png,
ai_pipeline_steps_detailed.html/.png, study_workflow_AI_to_MR.html/.png,
figure2_mr_study_design.png) were hand-produced one-off images, not
generated by any script in the pipeline -- meaning every number in them had
to be kept in sync with the underlying analysis BY HAND, which is exactly
how the original ai_pipeline_steps_detailed diagram ended up encoding the
pre-fix numbers (35.6% MetS+ prevalence, "86% missing, worst var" for
ALQ111, "SMOTE" instead of "SMOTENC") as a static image with no traceable
source of truth.

REBUILD NOTE / FIX: this script makes that class of drift structurally
impossible going forward by generating both diagrams that summarize
pipeline numbers (figure1_data_cleaning_pipeline.png and
ai_pipeline_steps_detailed.html/.png) directly from the same CSV outputs
every other script reads and writes -- there is no hand-typed number left
anywhere in this file. It also regenerates study_workflow_AI_to_MR.html/.png
unchanged in content (it never encoded a since-fixed number) purely for
reproducibility, so every diagram in diagrams/ now has a script behind it.
2026-10 audit (P2): figure2_mr_study_design.png (proposal Figure 2) is now
drawn here too; the hand-made version still named a removed claim.

Output: diagrams/figure1_data_cleaning_pipeline.png
        diagrams/ai_pipeline_steps_detailed.html
        diagrams/ai_pipeline_steps_detailed.png
        diagrams/study_workflow_AI_to_MR.html
        diagrams/study_workflow_AI_to_MR.png
        diagrams/figure2_mr_study_design.png

Run (after the full pipeline, 01 through 13, has been run at least once --
every number below is read from their outputs, not computed here):
    python 06_Code/14_generate_diagrams.py
"""
import json
import subprocess
import sys
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
import pandas as pd

sys.path.insert(0, str(Path(__file__).resolve().parent))
import config as cfg

DIAGRAMS_DIR = cfg.PROJECT_ROOT / "diagrams"
DIAGRAMS_DIR.mkdir(parents=True, exist_ok=True)


def _require(path: Path, produced_by: str) -> Path:
    if not path.exists():
        raise SystemExit(f"{path} not found -- run {produced_by} first (see that script's docstring).")
    return path


def load_pipeline_numbers() -> dict:
    """Every figure number below, read from the actual pipeline outputs --
    see module docstring for why this replaces hand-typed values."""
    n = {}

    excl = pd.read_csv(_require(cfg.OUT_METRICS / "exclusion_flow.csv", "02_clean_and_outcome.py"))
    # read by position (2026-10 audit: two exclusion steps were added, so the
    # earlier lookups by exact step label broke)
    rem = excl["n_remaining"].astype(int).tolist()
    exc = excl["n_excluded_this_step"].fillna(0).astype(int).tolist()
    n["n_pooled"] = rem[0]
    n["n_age20"], n["n_excl_age"] = rem[1], exc[1]
    n["n_not_preg"], n["n_excl_preg"] = rem[2], exc[2]
    n["n_complete_mets"], n["n_excl_mets"] = rem[3], exc[3]
    n["n_fasted"], n["n_excl_fasting"] = rem[4], exc[4]
    n["n_final"], n["n_excl_metals"] = rem[5], exc[5]

    outc = pd.read_csv(_require(cfg.OUT_METRICS / "outcome_definition_comparison.csv", "02_clean_and_outcome.py"))
    harm = outc[outc["definition"].str.startswith("harmonized")].iloc[0]
    labonly = outc[outc["definition"].str.startswith("lab_only")].iloc[0]
    n["mets_pos_harmonized"] = int(harm["n_positive"])
    n["mets_pct_harmonized"] = float(harm["prevalence_pct"])
    n["mets_pos_labonly"] = int(labonly["n_positive"])
    n["mets_pct_labonly"] = float(labonly["prevalence_pct"])
    n["n_reclassified"] = int(harm["n_reclassified_negative_to_positive"])

    preds = pd.read_csv(_require(cfg.OUT_METRICS / "predictors_used.csv", "03_feature_engineering.py"))
    n["n_predictors"] = len(preds)

    train_seqn = pd.read_csv(_require(cfg.DATA_PROC_DIR / "train_seqn.csv", "04_split.py"))
    test_seqn = pd.read_csv(_require(cfg.DATA_PROC_DIR / "test_seqn.csv", "04_split.py"))
    n["n_train"] = len(train_seqn)
    n["n_test"] = len(test_seqn)

    miss = pd.read_csv(_require(cfg.OUT_METRICS / "missingness_report.csv", "02_clean_and_outcome.py"))
    pred_base = set()
    for p in preds["predictor"]:
        pred_base.add(p.split("_")[0] if (p.startswith("RIDRETH1_") or p.startswith("DMDMARTL_")) else p)
    miss_preds = miss[miss["variable"].isin(pred_base)].sort_values("pct_missing", ascending=False)
    worst = miss_preds.iloc[0]
    n["worst_missing_var"] = cfg.label_feature(worst["variable"])
    n["worst_missing_var_code"] = worst["variable"]
    n["worst_missing_pct"] = float(worst["pct_missing"])

    # Steps 10-13: model results (only available after 06-10 have been run)
    cmp_path = cfg.OUT_METRICS / "model_comparison.csv"
    if cmp_path.exists():
        cmp_df = pd.read_csv(cmp_path).sort_values("AUC", ascending=False).reset_index(drop=True)
        n["best_model"] = cmp_df.iloc[0]["Model"]
        n["best_auc"] = float(cmp_df.iloc[0]["AUC"])
        if "statistically_indistinguishable_from_top" in cmp_df.columns:
            n["n_tied"] = int(cmp_df["statistically_indistinguishable_from_top"].sum()) - 1
        else:
            n["n_tied"] = None
    else:
        n["best_model"] = n["best_auc"] = n["n_tied"] = None

    shap_path = cfg.OUT_METRICS / "shap_importance.csv"
    if shap_path.exists():
        shap_df = pd.read_csv(shap_path).sort_values("mean_abs_shap", ascending=False).reset_index(drop=True)
        n["top1_feature"] = shap_df.iloc[0]["clinical_name"]
        n["top2_feature"] = shap_df.iloc[1]["clinical_name"] if len(shap_df) > 1 else None
    else:
        n["top1_feature"] = n["top2_feature"] = None

    sens_paths = {
        "diq010": cfg.OUT_METRICS / "sensitivity_diq010.csv",
        "smote_vs_cw": cfg.OUT_METRICS / "sensitivity_smote_vs_classweight.csv",
        "metals_scope": cfg.OUT_METRICS / "sensitivity_metals_scope.csv",
        "outcome_def": cfg.OUT_METRICS / "sensitivity_outcome_definition.csv",
    }
    deltas = []
    n_sensitivity_arms = 0
    for key, p in sens_paths.items():
        if p.exists():
            n_sensitivity_arms += 1
            d = pd.read_csv(p)
            if "delta" in d.columns:
                deltas.extend(pd.to_numeric(d["delta"], errors="coerce").dropna().abs().tolist())
    n["n_sensitivity_arms"] = n_sensitivity_arms
    n["max_abs_sensitivity_delta"] = max(deltas) if deltas else None

    n["n_modules"] = len(cfg.MODULES)
    n["module_list"] = ", ".join(cfg.MODULES)
    return n


# ============================================================
# Figure 1: data-cleaning pipeline (matplotlib box flowchart)
# ============================================================
def build_figure1(n: dict):
    """Plain data coordinates (not axes-fraction), with each box's height
    computed from its own subtitle line count rather than a fixed row plan
    -- an earlier draft used axes-fraction coordinates on a fixed,
    oversized figsize (left a large blank region below the last box, since
    bbox_inches='tight' had nothing near the bottom of a 0-1 axes span to
    crop to) and then a fixed-row-height version (title and subtitle text
    still collided whenever a box's actual text needed more vertical room
    than its allotted row). Title is anchored at a fixed offset from the
    box top and the subtitle flows downward from directly below it, so
    height always matches content instead of the reverse."""
    blue_e, blue_f = "#1F3864", "#DCE6F5"
    green_e, green_f = "#1B5E3F", "#DCF0E4"
    tan_e, tan_f = "#8A5A12", "#FBEFDA"
    W = 12.0
    TITLE_H, LINE_H, PAD_TOP, PAD_BOT = 0.32, 0.245, 0.16, 0.26

    def box_height(subtitle, fontsize_title=14.5):
        n_lines = subtitle.count("\n") + 1
        return PAD_TOP + TITLE_H + 0.06 + n_lines * LINE_H + PAD_BOT

    def box(x, y, w, title, subtitle, color_edge, color_face, fontsize_title=14.5, fontsize_sub=10.5):
        h = box_height(subtitle, fontsize_title)
        b = mpatches.FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0.03,rounding_size=0.08",
                                     linewidth=1.8, edgecolor=color_edge, facecolor=color_face)
        ax.add_patch(b)
        ax.text(x + w / 2, y + PAD_TOP, title, ha="center", va="top",
                 fontsize=fontsize_title, fontweight="bold", color=color_edge)
        ax.text(x + w / 2, y + PAD_TOP + TITLE_H + 0.06, subtitle, ha="center", va="top",
                 fontsize=fontsize_sub, linespacing=1.65)
        return h

    def arrow(x, y_top, y_bot):
        ax.annotate("", xy=(x, y_bot), xytext=(x, y_top),
                     arrowprops=dict(arrowstyle="-|>", color="#1F3864", lw=1.8))

    def excl_note(y, text):
        ax.text(W - 0.05, y, text, ha="left", va="center", fontsize=9.7, color="#A33", style="italic")

    # --- Pass 1: lay out on a throwaway figure just to compute total height ---
    fig, ax = plt.subplots(figsize=(W, 20))
    ax.set_xlim(0, W)
    ax.axis("off")

    GAP = 0.55
    y = 0.15 + 0.5  # title reserve
    box1_sub = f"Merged {n['n_modules']} modules ({n['module_list']}), all six 2-year cycles; n = {n['n_pooled']:,}"
    box2_sub = f"n = {n['n_age20']:,}"
    box2b_sub = f"n = {n['n_not_preg']:,}"
    box3_sub = (f"Waist circumference, mean systolic/diastolic BP, HDL-C, triglycerides, fasting glucose\n"
                f"n = {n['n_complete_mets']:,}")
    box3b_sub = f"Fasted 8 to 24 h (non-zero NCHS fasting weight); n = {n['n_fasted']:,}"
    box4_sub = f"Lead, cadmium, mercury, selenium, manganese. FINAL ANALYTIC COHORT: n = {n['n_final']:,}"
    outcome_sub = (f"Harmonized criteria (Alberti et al. 2009):\nmeasured threshold OR drug treatment "
                   f"(BPQ050A / BPQ100D / DIQ050 / DIQ070)\n\n"
                   f"MetS+: n = {n['mets_pos_harmonized']:,} ({n['mets_pct_harmonized']:.1f}%)\n"
                   f"[lab-only definition: {n['mets_pct_labonly']:.1f}%; {n['n_reclassified']:,} reclassified]")
    predictor_sub = (f"{n['n_predictors']} predictors: 5 blood metals + demographic /\nanthropometric / lifestyle covariates\n\n"
                      f"All 5 MetS-defining components AND all 4\nmedication-status variables EXCLUDED (leakage-safe by design)")
    final_sub = (f"n = {n['n_final']:,} participants × {n['n_predictors']} predictors + 1 outcome label\n\n"
                 f"Worst-missing predictor: {n['worst_missing_var']} ({n['worst_missing_pct']:.1f}% missing), imputed "
                 f"and flagged with an always-present\nmissing-value indicator, inside each cross-validation fold only, "
                 f"never before the train/test split\n\n"
                 f"Stratified 80/20 split (Sec. 3.1.6): {n['n_train']:,} train / {n['n_test']:,} test")

    h1 = box_height(box1_sub); y1 = y; y += h1 + GAP
    h2 = box_height(box2_sub); y2 = y; y += h2 + GAP
    h2b = box_height(box2b_sub); y2b = y; y += h2b + GAP
    h3 = box_height(box3_sub); y3 = y; y += h3 + GAP
    h3b = box_height(box3b_sub); y3b = y; y += h3b + GAP
    h4 = box_height(box4_sub); y4 = y; y += h4 + 0.7
    h_split = max(box_height(outcome_sub), box_height(predictor_sub)); y5 = y; y += h_split + 0.55
    h_final = box_height(final_sub); y6 = y; y += h_final + 0.45
    total_h = y  # + legend line
    plt.close(fig)

    # --- Pass 2: real figure, sized exactly to total_h ---
    fig, ax = plt.subplots(figsize=(W, total_h))
    ax.set_xlim(0, W)
    ax.set_ylim(0, total_h)
    ax.axis("off")
    ax.invert_yaxis()  # y increases downward, matching the top-to-bottom layout above

    ax.text(W / 2, 0.15, "Figure 1. Data-Cleaning Pipeline for the Machine-Learning Analysis",
            ha="center", va="top", fontsize=17, fontweight="bold", color="#1F3864")

    box(0.6, y1, W - 1.2, "NHANES 2007–2018: 6 pooled cycles", box1_sub, blue_e, blue_f, fontsize_sub=10.2)
    arrow(W / 2, y1 + h1, y2)

    box(0.6, y2, W - 1.2, "Age ≥ 20 years", box2_sub, blue_e, blue_f)
    excl_note(y2 + h2 / 2, f"Excluded (age < 20 years):\nn = {n['n_excl_age']:,}")
    arrow(W / 2, y2 + h2, y2b)

    box(0.6, y2b, W - 1.2, "Not pregnant", box2b_sub, blue_e, blue_f)
    excl_note(y2b + h2b / 2, f"Excluded (pregnant):\nn = {n['n_excl_preg']:,}")
    arrow(W / 2, y2b + h2b, y3)

    box(0.6, y3, W - 1.2, "Complete data on all 5 MetS lab/exam components", box3_sub, blue_e, blue_f, fontsize_sub=10.2)
    excl_note(y3 + h3 / 2, f"Excluded (missing ≥1 of 5\nMetS components):\nn = {n['n_excl_mets']:,}")
    arrow(W / 2, y3 + h3, y3b)

    box(0.6, y3b, W - 1.2, "Met the fasting criterion", box3b_sub, blue_e, blue_f, fontsize_sub=10.2)
    excl_note(y3b + h3b / 2, f"Excluded (did not meet\nfasting criterion):\nn = {n['n_excl_fasting']:,}")
    arrow(W / 2, y3b + h3b, y4)

    box(0.6, y4, W - 1.2, "At least 1 of 5 blood metals measured", box4_sub, green_e, green_f)
    excl_note(y4 + h4 / 2, f"Excluded (no blood metal\nmeasured): n = {n['n_excl_metals']:,}")

    box(0.6, y5, 5.1, "Outcome labeling", outcome_sub, tan_e, tan_f, fontsize_title=13.5, fontsize_sub=9.8)
    box(6.3, y5, 5.1, "Predictor set assembly", predictor_sub, tan_e, tan_f, fontsize_title=13.5, fontsize_sub=9.8)
    ax.annotate("", xy=(3.15, y5), xytext=(W / 2, y4 + h4 + 0.1),
                arrowprops=dict(arrowstyle="-|>", color="#1F3864", lw=1.6, connectionstyle="arc3,rad=0.25"))
    ax.annotate("", xy=(8.85, y5), xytext=(W / 2, y4 + h4 + 0.1),
                arrowprops=dict(arrowstyle="-|>", color="#1F3864", lw=1.6, connectionstyle="arc3,rad=-0.25"))

    box(0.6, y6, W - 1.2, "Model-ready analytic dataset", final_sub, blue_e, blue_f, fontsize_sub=10.3)
    ax.annotate("", xy=(3.15, y6), xytext=(3.15, y5 + h_split + 0.08),
                arrowprops=dict(arrowstyle="-|>", color="#1F3864", lw=1.6, connectionstyle="arc3,rad=0.2"))
    ax.annotate("", xy=(8.85, y6), xytext=(8.85, y5 + h_split + 0.08),
                arrowprops=dict(arrowstyle="-|>", color="#1F3864", lw=1.6, connectionstyle="arc3,rad=-0.2"))

    ax.text(0.6, y6 + h_final + 0.28,
            "Blue: cohort assembly steps     Green: final analytic cohort     Tan: outcome & predictor construction",
            va="top", fontsize=10, color="#555")

    out_path = DIAGRAMS_DIR / "figure1_data_cleaning_pipeline.png"
    plt.savefig(out_path, dpi=150, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    print(f"  saved: {out_path}")


# ============================================================
# ai_pipeline_steps_detailed.html/.png (SVG timeline, matching the
# original file's exact markup style, rendered to PNG via Playwright)
# ============================================================
STEP_TEMPLATE = (
    '<rect class="box" x="40" y="{y}" width="600" height="76" rx="4"/>'
    '<g class="{color}"><circle cx="40" cy="{cy}" r="17"/>'
    '<text class="th" x="40" y="{cy_text}" text-anchor="middle">{num}</text></g>'
    '<text class="th" x="64" y="{title_y}">{title}</text>'
    '<text class="ts" x="64" y="{sub_y}">{subtitle}</text>'
    '<g class="{color}"><rect class="{color}" x="390" y="{pill_y}" width="240" height="30" rx="15"/>'
    '<text class="ts" x="510.0" y="{pill_text_y}" text-anchor="middle">{stat}</text></g>'
)
ARROW_TEMPLATE = '<line class="arr" x1="40" y1="{y1}" x2="40" y2="{y2}" marker-end="url(#arrow)"/>'


def build_ai_pipeline_svg(n: dict) -> str:
    steps = [
        ("1", "blue", "Pooled NHANES Sample", "6 cycles, 2007–2018", f"n = {n['n_pooled']:,}"),
        ("2", "blue", "Age Filter", "Adults 20 years and older", f"n = {n['n_age20']:,} (−{n['n_excl_age']:,})"),
        ("3", "blue", "Exclusions", "Pregnant; incomplete MetS data; not fasted",
         f"n = {n['n_fasted']:,} (−{n['n_excl_preg'] + n['n_excl_mets'] + n['n_excl_fasting']:,})"),
        ("4", "blue", "Exposure Availability", "At least 1 metal measured",
         f"n = {n['n_final']:,} (−{n['n_excl_metals']:,})"),
        ("5", "blue", "Outcome Labeling", "Harmonized MetS (Alberti 2009)",
         f"{n['mets_pct_harmonized']:.1f}% MetS+ (n={n['mets_pos_harmonized']:,})"),
        ("6", "blue", "Feature Engineering", f"{n['n_predictors']} predictors, zero leakage",
         "5 metals + demographic/lifestyle"),
        ("7", "blue", "Train / Test Split", "Stratified 80/20 split", f"{n['n_train']:,} / {n['n_test']:,}"),
        ("8", "blue", "Missing Data", "Imputed + flagged inside each CV fold",
         f"{n['worst_missing_pct']:.0f}% missing, worst var"),
        ("9", "blue", "Class Imbalance", "SMOTENC refit per fold only", "never touches test set"),
        ("10", "teal", "Hyperparameter Tuning", "Stratified CV, ROC AUC", "11 models, 10-fold CV"),
        ("11", "teal", "Held-Out Evaluation", "Test set opened once",
         (f"best AUC {n['best_auc']:.3f}, {n['best_model']}" if n["best_auc"] is not None else "pending")),
        ("12", "teal", "Interpretation", "SHAP + permutation",
         (f"{n['top1_feature']} #1" if n["top1_feature"] else "pending")),
        ("13", "teal", "Sensitivity Checks", f"{n['n_sensitivity_arms']} robustness analyses",
         (f"Δ ≤ {n['max_abs_sensitivity_delta']:.3f} AUC" if n["max_abs_sensitivity_delta"] is not None else "pending")),
    ]

    body = []
    y = 50
    for i, (num, color, title, subtitle, stat) in enumerate(steps):
        cy = y + 38
        body.append(STEP_TEMPLATE.format(
            y=y, color=f"c-{color}", cy=cy, cy_text=cy + 5, num=num,
            title_y=y + 30, title=title, sub_y=y + 50, subtitle=subtitle,
            pill_y=y + 23, pill_text_y=y + 42, stat=stat,
        ))
        if i < len(steps) - 1:
            body.append(ARROW_TEMPLATE.format(y1=y + 76, y2=y + 96))
        y += 104

    footer_y1, footer_y2 = y + 18, y + 34
    total_height = y + 60

    svg = f'''<!DOCTYPE html><html><head><meta charset='utf-8'><title>AI Pipeline Steps</title></head><body style='margin:0;padding:24px;background:#fff;'><svg width="100%" viewBox="0 0 680 {total_height}" role="img" xmlns="http://www.w3.org/2000/svg"><title>AI pipeline: thirteen steps from raw NHANES data to interpreted, sensitivity-checked models</title><desc>A vertical numbered timeline of thirteen steps, regenerated directly from outputs/metrics CSVs -- see 14_generate_diagrams.py.</desc><defs><style>
text{{font-family:'DejaVu Sans','Helvetica Neue',Arial,sans-serif;}}
.t{{font-size:14px;fill:#2C2C2A;}}
.th{{font-size:14px;font-weight:700;fill:#2C2C2A;}}
.ts{{font-size:12px;fill:#5F5E5A;}}
.box{{fill:#FFFFFF;stroke:#D3D1C7;stroke-width:1;}}
.arr{{stroke:#9C9A92;stroke-width:1.5;fill:none;}}
.c-blue{{fill:#E6F1FB;stroke:#185FA5;stroke-width:1;}}
.c-blue .th{{fill:#0C447C;}}
.c-blue .ts{{fill:#185FA5;}}
.c-teal{{fill:#E1F5EE;stroke:#0F6E56;stroke-width:1;}}
.c-teal .th{{fill:#085041;}}
.c-teal .ts{{fill:#0F6E56;}}
</style></defs><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M2 1L8 5L2 9" fill="none" stroke="context-stroke" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></marker></defs>{"".join(body)}<text class="ts" x="40" y="{footer_y1}">Blue: data preparation and cohort definition (steps 1–9).</text><text class="ts" x="40" y="{footer_y2}">Teal: model tuning, evaluation, and interpretation (steps 10–13).</text></svg></body></html>'''
    return svg


def render_html_to_png(html_path: Path, png_path: Path, width=960):
    # 2026-10 audit (C10): playwright is optional; without it the HTML version
    # of the diagram is still written and only the PNG rendering is skipped.
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        print(f"  [skip] playwright not installed: {png_path.name} not rendered (HTML kept)")
        return
    # This project's venv installs its own playwright package, whose pinned
    # browser revision doesn't match the cloud sandbox's pre-installed
    # Chromium -- point at that pre-installed binary directly rather than
    # downloading a duplicate copy (sandbox networking is allowlisted and
    # a fresh `playwright install` is not guaranteed to succeed here).
    preinstalled = Path("/opt/pw-browsers/chromium-1194/chrome-linux/chrome")
    launch_kwargs = {"executable_path": str(preinstalled)} if preinstalled.exists() else {}
    with sync_playwright() as p:
        browser = p.chromium.launch(**launch_kwargs)
        page = browser.new_page(viewport={"width": width, "height": 1200})
        page.goto(html_path.resolve().as_uri())
        page.wait_for_timeout(150)
        svg_box = page.eval_on_selector("svg", "el => { const r = el.getBoundingClientRect(); "
                                                "return {width: r.width, height: r.height}; }")
        page.set_viewport_size({"width": width, "height": int(svg_box["height"]) + 48})
        page.screenshot(path=str(png_path), full_page=True)
        browser.close()
    print(f"  saved: {png_path}")


def build_ai_pipeline_diagram(n: dict):
    html = build_ai_pipeline_svg(n)
    html_path = DIAGRAMS_DIR / "ai_pipeline_steps_detailed.html"
    html_path.write_text(html)
    print(f"  saved: {html_path}")
    png_path = DIAGRAMS_DIR / "ai_pipeline_steps_detailed.png"
    render_html_to_png(html_path, png_path)


# ============================================================
# study_workflow_AI_to_MR.html/.png -- unchanged content (no number here
# was among the flagged issues), regenerated purely so it, too, now has a
# script behind it rather than being a hand-authored one-off file.
