def build_study_workflow_svg(n: dict) -> str:
    return f'''<!DOCTYPE html><html><head><meta charset='utf-8'><title>Study Workflow</title></head><body style='margin:0;padding:24px;background:#fff;'><svg width="100%" viewBox="0 0 680 1000" role="img" xmlns="http://www.w3.org/2000/svg"><title>Study workflow: machine-learning phase followed by Mendelian randomization phase</title><desc>A vertical eight-step timeline. Steps 1 through 4, blue and solid, marked completed: Data and Cleaning, Feature Engineering, Modeling, Interpretation. Steps 5 through 8, teal and dashed, marked planned: Exposure Screening, Instrument Extraction, Causal Estimation, Robustness Checks. A legend notes solid boxes are completed with real data and dashed boxes are planned pending GWAS data access and ethics approval.</desc><defs><style>
text{{font-family:'DejaVu Sans','Helvetica Neue',Arial,sans-serif;}}
.t{{font-size:14px;fill:#2C2C2A;}}
.th{{font-size:14px;font-weight:700;fill:#2C2C2A;}}
.ts{{font-size:12px;fill:#5F5E5A;}}
.box{{fill:#FFFFFF;stroke:#D3D1C7;stroke-width:1;}}
.arr{{stroke:#9C9A92;stroke-width:1.5;fill:none;}}
.c-blue{{fill:#E6F1FB;stroke:#185FA5;stroke-width:1;}}
.c-blue .th{{fill:#0C447C;}}
.c-blue .ts{{fill:#185FA5;}}
.c-teal{{fill:#E1F5EE;stroke:#0F6E56;stroke-width:1;}}
.c-teal .th{{fill:#085041;}}
.c-teal .ts{{fill:#0F6E56;}}
</style></defs><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M2 1L8 5L2 9" fill="none" stroke="context-stroke" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></marker></defs><text class="th" x="40" y="40">PHASE 1 · MACHINE LEARNING: completed</text><rect class="c-blue" x="40" y="74" width="600" height="78" rx="4"/><g class="c-blue"><text class="th" x="64" y="106">Data &amp; Cleaning</text><text class="ts" x="64" y="128">NHANES 2007–2018 pooled, n={n['n_final']:,} final</text></g><line class="arr" x1="40" y1="156" x2="40" y2="176" marker-end="url(#arrow)"/><rect class="c-blue" x="40" y="180" width="600" height="78" rx="4"/><g class="c-blue"><text class="th" x="64" y="212">Feature Engineering</text><text class="ts" x="64" y="234">{n['n_predictors']} predictors, 80/20 split</text></g><line class="arr" x1="40" y1="262" x2="40" y2="282" marker-end="url(#arrow)"/><rect class="c-blue" x="40" y="286" width="600" height="78" rx="4"/><g class="c-blue"><text class="th" x="64" y="318">Modeling</text><text class="ts" x="64" y="340">11 algorithms tuned via 10-fold CV</text></g><line class="arr" x1="40" y1="368" x2="40" y2="388" marker-end="url(#arrow)"/><rect class="c-blue" x="40" y="392" width="600" height="78" rx="4"/><g class="c-blue"><text class="th" x="64" y="424">Interpretation</text><text class="ts" x="64" y="446">SHAP, permutation, sensitivity checks</text></g><text class="th" x="40" y="508">PHASE 2 · MENDELIAN RANDOMIZATION: planned</text><rect class="c-teal" x="40" y="528" width="600" height="78" rx="4" stroke-dasharray="4 3"/><g class="c-teal"><text class="th" x="64" y="560">Exposure Screening</text><text class="ts" x="64" y="582">AI-ranked predictors × GWAS instrument availability</text></g><line class="arr" x1="40" y1="610" x2="40" y2="630" marker-end="url(#arrow)"/><rect class="c-teal" x="40" y="634" width="600" height="78" rx="4" stroke-dasharray="4 3"/><g class="c-teal"><text class="th" x="64" y="666">Instrument Extraction</text><text class="ts" x="64" y="688">Harmonize SNP–exposure–outcome data</text></g><line class="arr" x1="40" y1="716" x2="40" y2="736" marker-end="url(#arrow)"/><rect class="c-teal" x="40" y="740" width="600" height="78" rx="4" stroke-dasharray="4 3"/><g class="c-teal"><text class="th" x="64" y="772">Causal Estimation</text><text class="ts" x="64" y="794">IVW plus four robust MR methods</text></g><line class="arr" x1="40" y1="822" x2="40" y2="842" marker-end="url(#arrow)"/><rect class="c-teal" x="40" y="846" width="600" height="78" rx="4" stroke-dasharray="4 3"/><g class="c-teal"><text class="th" x="64" y="878">Robustness Checks</text><text class="ts" x="64" y="900">Heterogeneity, pleiotropy, directionality tests</text></g><text class="ts" x="40" y="954">Solid boxes: completed, real NHANES data and model results.</text><text class="ts" x="40" y="970">Dashed boxes: planned next phase, pending GWAS data access and IRB/ethics approval.</text></svg></body></html>'''


def build_study_workflow_diagram(n: dict):
    html = build_study_workflow_svg(n)
    html_path = DIAGRAMS_DIR / "study_workflow_AI_to_MR.html"
    html_path.write_text(html)
    print(f"  saved: {html_path}")
    png_path = DIAGRAMS_DIR / "study_workflow_AI_to_MR.png"
    render_html_to_png(html_path, png_path)


# ============================================================
# Figure 2 of the proposal: MR study design (2026-10 audit, P2/P5/P6)
# ============================================================
MR_EXPOSURE_TIERS = {
    "Primary": "lead, selenium, body mass index",
    "Secondary": "cadmium",
    "Exploratory": "manganese, mercury\n(suggestive loci), alcohol,\nphysical activity",
}


def build_figure2_mr():
    """Proposal Figure 2, drawn from code. The earlier image was hand-made and
    still named a '13-SNP lead instrument' after that unverifiable claim had
    been removed from the text, and it showed the old exposure tiers."""
    W, H = 12.0, 10.2
    fig, ax = plt.subplots(figsize=(W, H))
    ax.set_xlim(0, W); ax.set_ylim(0, H); ax.axis("off")

    def box(x, y, w, h, title, body, edge, face):
        ax.add_patch(mpatches.FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0.02,rounding_size=0.08",
                                             linewidth=2.2, edgecolor=edge, facecolor=face))
        ax.text(x + w / 2, y + h - 0.42, title, ha="center", va="top", fontsize=15,
                fontweight="bold", color=edge)
        ax.text(x + w / 2, y + h - 1.05, body, ha="center", va="top", fontsize=10.8,
                linespacing=1.55, color="#222222")

    ax.text(W / 2, H - 0.25, "Figure 2. Mendelian randomization study design", ha="center", va="top",
            fontsize=18, fontweight="bold", color="#1F3864")
    ax.text(W / 2, H - 0.85, "Genetic variants as instrumental variables for blood-metal and metabolic "
            "exposures, outcomes = metabolic syndrome components", ha="center", va="top", fontsize=11.5,
            style="italic", color="#444444")

    zx, zy, zw, zh = 0.5, 5.6, 4.6, 2.9
    ux, uy, uw, uh = 6.9, 5.6, 4.6, 2.9
    xx, xy, xw, xh = 0.5, 1.3, 4.6, 3.1
    yx, yy, yw, yh = 6.9, 1.3, 4.6, 3.1
    box(zx, zy, zw, zh, "Z: genetic instruments",
        "SNPs per exposure (Table 1):\nmulti-element and toxic-metal GWAS\n(Pb, Cd, Mn), selenium GWAS (Se),\n"
        "GIANT (BMI), GSCAN (alcohol),\naccelerometer GWAS (activity)", "#1F3864", "#E8EEF8")
    box(ux, uy, uw, uh, "U: confounders",
        "Age, sex, ancestry and population\nstratification, socioeconomic\nposition, smoking, diet",
        "#5B3A7E", "#F1EAF7")
    tiers = "\n".join(f"{k}: {v}" for k, v in MR_EXPOSURE_TIERS.items())
    box(xx, xy, xw, xh, "X: exposures", tiers, "#1B6B4A", "#E6F3EC")
    box(yx, yy, yw, yh, "Y: outcomes",
        "Metabolic syndrome components,\nanalysed separately: waist\ncircumference, blood pressure,\n"
        "HDL-C, triglycerides, fasting glucose\n(GIANT / ICBP / GLGC / MAGIC)", "#9A6A1E", "#FBF2E2")

    arrow = dict(arrowstyle="-|>", lw=3.2, color="#1F3864", mutation_scale=26)
    ax.annotate("", xy=(zx + zw / 2, xy + xh + 0.08), xytext=(zx + zw / 2, zy - 0.08), arrowprops=arrow)
    ax.text(zx + zw / 2 - 0.15, (zy + xy + xh) / 2, "1  Relevance\n(F > 10)", ha="right", va="center",
            fontsize=12, fontweight="bold", color="#1F3864")
    ax.annotate("", xy=(yx - 0.1, xy + xh / 2), xytext=(xx + xw + 0.1, xy + xh / 2),
                arrowprops=dict(arrowstyle="-|>", lw=3.2, color="#1B6B4A", mutation_scale=26))
    ax.text((xx + xw + yx) / 2, xy + xh / 2 + 0.3, "causal\neffect (β)", ha="center", va="bottom",
            fontsize=12, fontweight="bold", color="#1B6B4A")
    conf = dict(arrowstyle="-|>", lw=2, color="#555555", ls=(0, (4, 3)), mutation_scale=18)
    ax.annotate("", xy=(xx + xw - 0.3, xy + xh + 0.05), xytext=(ux + 0.2, uy - 0.05), arrowprops=conf)
    ax.annotate("", xy=(yx + yw / 2, yy + yh + 0.05), xytext=(ux + uw / 2, uy - 0.05), arrowprops=conf)
    red = "#A33A2E"
    ax.plot([zx + zw + 0.1, ux - 0.1], [zy + zh / 2, zy + zh / 2], color=red, lw=2.6, ls=(0, (5, 4)))
    ax.text((zx + zw + ux) / 2, zy + zh / 2 + 0.25, "2  Independence\n(no Z–U path)", ha="center",
            va="bottom", fontsize=11.5, fontweight="bold", style="italic", color=red)
    ax.plot([zx + zw - 0.4, yx + 0.6], [zy - 0.1, yy + yh + 0.1], color=red, lw=2.6, ls=(0, (5, 4)))
    ax.text(7.95, 5.05, "3  Exclusion\nrestriction", ha="center", va="center",
            fontsize=11, fontweight="bold", style="italic", color=red)
    ax.plot([0.7, 1.5], [0.55, 0.55], color="#1F3864", lw=3)
    ax.text(1.65, 0.55, "path used by MR", va="center", fontsize=10.5, color="#333333")
    ax.plot([4.3, 5.1], [0.55, 0.55], color=red, lw=2.6, ls=(0, (5, 4)))
    ax.text(5.25, 0.55, "path that must be absent", va="center", fontsize=10.5, color="#333333")
    ax.plot([8.4, 9.2], [0.55, 0.55], color="#555555", lw=2, ls=(0, (4, 3)))
    ax.text(9.35, 0.55, "confounding (bypassed)", va="center", fontsize=10.5, color="#333333")
    out = DIAGRAMS_DIR / "figure2_mr_study_design.png"
    fig.savefig(out, dpi=200, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    print(f"  saved: {out}")


def main():
    print("Loading pipeline numbers from outputs/metrics/*.csv...")
    n = load_pipeline_numbers()
    if n["best_auc"] is None:
        print("  [NOTE] model_comparison.csv not found yet -- steps 10-13 of ai_pipeline_steps_detailed "
              "will show 'pending' until 06-13 have been run. Re-run this script after the full pipeline "
              "completes to fill them in.")

    print("\n[1/3] Figure 1: data-cleaning pipeline...")
    build_figure1(n)

    print("\n[2/3] AI pipeline steps (13-step timeline)...")
    build_ai_pipeline_diagram(n)

    print("\n[3/4] Study workflow (AI phase -> MR phase)...")
    build_study_workflow_diagram(n)

    print("\n[4/4] Figure 2: MR study design...")
    build_figure2_mr()


if __name__ == "__main__":
    main()
